'use client';

import React, { useState } from 'react';
import { Card, Button, Badge, Input } from '@/components/ui/base';
import { Search, Filter, Download, Trash2, MoreHorizontal, Plus, RefreshCw, Clock } from 'lucide-react';
import { AddTransactionModal } from '@/components/ui/add-transaction-modal';
import { useTransactions } from '@/lib/transaction-context';

export default function TransactionsPage() {
  const [selected, setSelected] = useState<string[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const { transactions, deleteTransaction } = useTransactions();
  const [searchTerm, setSearchTerm] = useState('');
  const [typeFilter, setTypeFilter] = useState('All Types');

  const toggleSelect = (id: string) => {
    if (selected.includes(id)) {
      setSelected(selected.filter(item => item !== id));
    } else {
      setSelected([...selected, id]);
    }
  };

  const handleDelete = () => {
    selected.forEach(id => deleteTransaction(id));
    setSelected([]);
  };

  const filteredTransactions = transactions.filter(tx => {
    const matchesSearch = tx.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          tx.category.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesType = typeFilter === 'All Types' || tx.type === typeFilter;
    return matchesSearch && matchesType;
  });

  return (
    <div className="space-y-6">
      <AddTransactionModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />

      {/* Header */}
      <div className="bg-[#111827] text-white p-8 rounded-2xl shadow-lg -mt-4">
        <div className="flex justify-between items-center">
          <div>
            <h1 className="text-4xl font-bold mb-2">All Transactions</h1>
            <p className="text-gray-400 text-lg">Showing all transactions</p>
          </div>
          <div className="flex gap-4">
            <Button variant="outline" className="text-white border-gray-600 hover:bg-gray-800 gap-2 text-base">
              <Download size={20} /> Bulk Import
            </Button>
            <Button variant="primary" className="gap-2 text-base" onClick={() => setIsModalOpen(true)}>
              <Plus size={20} /> Add Transaction
            </Button>
          </div>
        </div>
      </div>

      {/* Filters & Table */}
      <Card className="p-6">
        <div className="flex flex-col md:flex-row justify-between items-center gap-4 mb-6">
          <div className="flex items-center gap-4 w-full md:w-auto">
            <div className="relative w-full md:w-64">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
              <Input 
                placeholder="Search transactions..." 
                className="pl-10 text-base" 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <select 
              className="bg-white border border-gray-300 rounded-md px-4 py-2 text-base focus:ring-2 focus:ring-green-500"
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value)}
            >
              <option>All Types</option>
              <option>Income</option>
              <option>Expense</option>
            </select>
            <button 
              className="text-gray-500 hover:text-gray-700 text-base font-medium"
              onClick={() => { setSearchTerm(''); setTypeFilter('All Types'); }}
            >
              × Reset
            </button>
          </div>
          
          {selected.length > 0 && (
            <Button variant="danger" size="sm" className="gap-2 text-base" onClick={handleDelete}>
              <Trash2 size={18} /> Delete ({selected.length})
            </Button>
          )}
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-base text-left">
            <thead className="text-sm text-gray-500 uppercase bg-gray-50 border-b">
              <tr>
                <th className="p-4 w-4">
                  <input type="checkbox" className="rounded border-gray-300 text-green-600 focus:ring-green-500 w-5 h-5" />
                </th>
                <th className="px-6 py-4">Date</th>
                <th className="px-6 py-4">Description</th>
                <th className="px-6 py-4">Category</th>
                <th className="px-6 py-4">Type</th>
                <th className="px-6 py-4">Amount</th>
                <th className="px-6 py-4">Payment Method</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4"></th>
              </tr>
            </thead>
            <tbody>
              {filteredTransactions.map((tx) => (
                <tr key={tx.id} className="bg-white border-b hover:bg-gray-50">
                  <td className="p-4 w-4">
                    <input 
                      type="checkbox" 
                      checked={selected.includes(tx.id)}
                      onChange={() => toggleSelect(tx.id)}
                      className="rounded border-gray-300 text-green-600 focus:ring-green-500 w-5 h-5" 
                    />
                  </td>
                  <td className="px-6 py-4 text-gray-500">{tx.date}</td>
                  <td className="px-6 py-4 font-medium text-gray-900">{tx.description}</td>
                  <td className="px-6 py-4 text-gray-500">{tx.category}</td>
                  <td className="px-6 py-4">
                    <Badge variant={tx.type === 'Income' ? 'success' : 'danger'}>
                      {tx.type.toUpperCase()}
                    </Badge>
                  </td>
                  <td className={`px-6 py-4 font-bold text-lg ${tx.type === 'Income' ? 'text-green-600' : 'text-red-600'}`}>
                    {tx.type === 'Income' ? '+' : '-'}₹{tx.amount.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                  </td>
                  <td className="px-6 py-4 text-gray-500">{tx.paymentMethod}</td>
                  <td className="px-6 py-4">
                    <span className={`px-2 py-1 rounded-full text-sm font-medium ${
                      tx.status === 'Completed' ? 'bg-green-100 text-green-800' : 
                      tx.status === 'Pending' ? 'bg-yellow-100 text-yellow-800' : 'bg-red-100 text-red-800'
                    }`}>
                      {tx.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <button className="text-gray-400 hover:text-gray-600">
                      <MoreHorizontal size={20} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        
        {/* Pagination Placeholder */}
        <div className="flex justify-between items-center mt-4 text-sm text-gray-500">
          <p>Showing {filteredTransactions.length} transactions</p>
        </div>
      </Card>
    </div>
  );
}
